<?php require_once __DIR__ . '/_guard.php'; $month=(int)date('n'); $year=(int)date('Y'); $first=new DateTime("$year-$month-01"); $days=(int)$first->format('t'); $start=(int)$first->format('N'); ?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mi horario</title><link rel="stylesheet" href="../css/base.css"><link rel="stylesheet" href="../css/components.css"><link rel="stylesheet" href="../css/client.css"></head><body><?php require __DIR__.'/_sidebar.php'; ?><main class="client-page"><h1>Mi horario</h1><p class="client-page-subtitle">Calendario personal de tus reservas. La disponibilidad general del salón se diseñará más adelante con las necesidades del administrador.</p><section class="client-card"><div class="client-calendar"><h2><?= htmlspecialchars(strftime('%B %Y')) ?></h2><table><thead><tr><th>L</th><th>M</th><th>X</th><th>J</th><th>V</th><th>S</th><th>D</th></tr></thead><tbody><tr><?php for($i=1;$i<$start;$i++) echo '<td></td>'; for($d=1;$d<=$days;$d++){ if(($start+$d-1)%7===1 && $d>1) echo '</tr><tr>'; $cls=$d==(int)date('j')?' class="today"':''; echo '<td'.$cls.'>'.$d.'</td>'; } $filled=($start+$days-1)%7; if($filled){for($i=$filled;$i<7;$i++)echo '<td></td>';} ?></tr></tbody></table></div><div class="client-empty">Cuando existan reservas, aquí se mostrarán sus horarios dentro del día correspondiente.</div></section></main><script src="../js/client.js"></script></body></html>